from django.db import migrations


def fill_status(apps, schema_editor):
    # 用 apps.get_model 拿历史模型，不能 import 当前 models.Post，
    # 否则以后改了模型这个迁移就跑不动了
    Post = apps.get_model('blog', 'Post')
    # 加 status 字段时 8 篇全被填成默认值 draft，
    # 这里按「有没有发布时间」回填，把已发布的文章恢复出来
    Post.objects.filter(published_date__isnull=False).update(status='published')


def clear_status(apps, schema_editor):
    # 反向操作：回滚时把状态全部重置为 draft（不删数据）
    Post = apps.get_model('blog', 'Post')
    Post.objects.all().update(status='draft')


